/**
 * Unified error type exposed across the FFI boundary.
 *
 * Every fallible FFI function returns `Result<T, FfiError>`.
 * The `From<anyhow::Error>` impl inspects the error chain with
 * `downcast_ref` to pick the most specific variant; anything
 * unrecognised falls through to `Unknown`.
 */
sealed class FfiException: kotlin.Exception() {
    
    class AuthenticationException(
        
        override val message: kotlin.String
        ) : FfiException() {
    }
    
    class DatabaseException(
        
        override val message: kotlin.String
        ) : FfiException() {
    }
    
    class SyncException(
        
        override val message: kotlin.String
        ) : FfiException() {
    }
    
    class ReportException(
        
        override val message: kotlin.String
        ) : FfiException() {
    }
    
    class ValidationException(
        
        override val message: kotlin.String
        ) : FfiException() {
    }
    
    class Unknown(
        
        override val message: kotlin.String
        ) : FfiException() {
    }
    

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<FfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): FfiException = FfiConverterTypeFfiError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeFfiError : FfiConverterRustBuffer<FfiException> {
    override fun read(buf: ByteBuffer): FfiException {
        

        return when(buf.getInt()) {
            1 -> FfiException.AuthenticationException(
                FfiConverterString.read(buf),
                )
            2 -> FfiException.DatabaseException(
                FfiConverterString.read(buf),
                )
            3 -> FfiException.SyncException(
                FfiConverterString.read(buf),
                )
            4 -> FfiException.ReportException(
                FfiConverterString.read(buf),
                )
            5 -> FfiException.ValidationException(
                FfiConverterString.read(buf),
                )
            6 -> FfiException.Unknown(
                FfiConverterString.read(buf),
                )
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: FfiException): ULong {
        return when(value) {
            is FfiException.AuthenticationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiException.DatabaseException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiException.SyncException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiException.ReportException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiException.ValidationException -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
            is FfiException.Unknown -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
                + FfiConverterString.allocationSize(value.`message`)
            )
        }
    }

    override fun write(value: FfiException, buf: ByteBuffer) {
        when(value) {
            is FfiException.AuthenticationException -> {
                buf.putInt(1)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiException.DatabaseException -> {
                buf.putInt(2)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiException.SyncException -> {
                buf.putInt(3)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiException.ReportException -> {
                buf.putInt(4)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiException.ValidationException -> {
                buf.putInt(5)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
            is FfiException.Unknown -> {
                buf.putInt(6)
                FfiConverterString.write(value.`message`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




